```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>CS:GO Arena</title>

  <style>
    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
      font-family: Arial, Helvetica, sans-serif;
    }

    body {
      background: #0d0d0d;
      color: #ffffff;
      line-height: 1.6;
    }

    header {
      background: linear-gradient(rgba(0, 0, 0, 0.75), rgba(0, 0, 0, 0.75)),
        url("https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&w=1600&q=80");
      background-size: cover;
      background-position: center;
      min-height: 100vh;
      display: flex;
      flex-direction: column;
    }

    nav {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 25px 8%;
      background: rgba(0, 0, 0, 0.65);
      position: sticky;
      top: 0;
      z-index: 1000;
    }

    .logo {
      font-size: 28px;
      font-weight: bold;
      color: #f5a623;
      letter-spacing: 2px;
    }

    .logo span {
      color: #ffffff;
    }

    nav ul {
      list-style: none;
      display: flex;
      gap: 25px;
    }

    nav ul li a {
      color: #ffffff;
      text-decoration: none;
      font-size: 16px;
      transition: 0.3s;
    }

    nav ul li a:hover {
      color: #f5a623;
    }

    .hero {
      flex: 1;
      display: flex;
      align-items: center;
      justify-content: center;
      text-align: center;
      padding: 0 10%;
    }

    .hero-content h1 {
      font-size: 64px;
      text-transform: uppercase;
      margin-bottom: 20px;
      color: #f5a623;
    }

    .hero-content p {
      font-size: 22px;
      max-width: 800px;
      margin: 0 auto 30px;
      color: #dddddd;
    }

    .btn {
      display: inline-block;
      padding: 14px 30px;
      background: #f5a623;
      color: #000000;
      text-decoration: none;
      font-weight: bold;
      border-radius: 4px;
      transition: 0.3s;
    }

    .btn:hover {
      background: #ffffff;
      color: #000000;
    }

    section {
      padding: 80px 8%;
    }

    .section-title {
      text-align: center;
      font-size: 38px;
      margin-bottom: 50px;
      color: #f5a623;
      text-transform: uppercase;
    }

    .about {
      background: #151515;
    }

    .about-content {
      max-width: 1000px;
      margin: auto;
      text-align: center;
      color: #cccccc;
      font-size: 18px;
    }

    .cards {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
      gap: 30px;
    }

    .card {
      background: #1c1c1c;
      padding: 30px;
      border-radius: 8px;
      text-align: center;
      border: 1px solid #333333;
      transition: 0.3s;
    }

    .card:hover {
      transform: translateY(-8px);
      border-color: #f5a623;
    }

    .card h3 {
      color: #f5a623;
      margin-bottom: 15px;
      font-size: 24px;
    }

    .card p {
      color: #cccccc;
      font-size: 16px;
    }

    .weapons {
      background: #101010;
    }

    .weapon-card img {
      width: 100%;
      height: 180px;
      object-fit: cover;
      border-radius: 6px;
      margin-bottom: 15px;
    }

    .maps {
      background: #151515;
    }

    .map-card {
      min-height: 260px;
      display: flex;
      flex-direction: column;
      justify-content: flex-end;
      background-size: cover;
      background-position: center;
      border-radius: 8px;
      overflow: hidden;
      position: relative;
    }

    .map-card::before {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(transparent, rgba(0, 0, 0, 0.9));
    }

    .map-card div {
      position: relative;
      padding: 25px;
    }

    .map-card h3 {
      color: #f5a623;
      font-size: 24px;
    }

    .map-card p {
      color: #dddddd;
    }

    .stats {
      background: #101010;
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
      gap: 30px;
      text-align: center;
    }

    .stat-box {
      background: #1c1c1c;
      padding: 30px;
      border-radius: 8px;
      border: 1px solid #333333;
    }

    .stat-box h3 {
      font-size: 40px;
      color: #f5a623;
    }

    .stat-box p {
      color: #cccccc;
      margin-top: 10px;
    }

    .contact {
      background: #151515;
    }

    form {
      max-width: 700px;
      margin: auto;
      display: flex;
      flex-direction: column;
      gap: 20px;
    }

    input,
    textarea {
      padding: 15px;
      border: none;
      outline: none;
      border-radius: 4px;
      background: #222222;
      color: #ffffff;
      font-size: 16px;
    }

    textarea {
      resize: vertical;
      min-height: 140px;
    }

    button {
      padding: 15px;
      background: #f5a623;
      border: none;
      color: #000000;
      font-weight: bold;
      font-size: 16px;
      cursor: pointer;
      border-radius: 4px;
      transition: 0.3s;
    }

    button:hover {
      background: #ffffff;
    }

    footer {
      background: #050505;
      text-align: center;
      padding: 25px;
      color: #aaaaaa;
      font-size: 14px;
    }

    .menu-toggle {
      display: none;
      font-size: 28px;
      cursor: pointer;
      color: #f5a623;
    }

    @media (max-width: 768px) {
      nav ul {
        position: absolute;
        top: 75px;
        right: 0;
        width: 100%;
        background: #000000;
        flex-direction: column;
        text-align: center;
        display: none;
        padding: 20px 0;
      }

      nav ul.active {
        display: flex;
      }

      .menu-toggle {
        display: block;
      }

      .hero-content h1 {
        font-size: 42px;
      }

      .hero-content p {
        font-size: 18px;
      }
    }
  </style>
</head>

<body>
  <header id="home">
    <nav>
      <div class="logo">CS:GO <span>Arena</span></div>

      <div class="menu-toggle" onclick="toggleMenu()">☰</div>

      <ul id="menu">
        <li><a href="#home">Home</a></li>
        <li><a href="#about">About</a></li>
        <li><a href="#weapons">Weapons</a></li>
        <li><a href="#maps">Maps</a></li>
        <li><a href="#stats">Stats</a></li>
        <li><a href="#contact">Contact</a></li>
      </ul>
    </nav>

    <div class="hero">
      <div class="hero-content">
        <h1>Counter-Strike: Global Offensive</h1>
        <p>
          Enter the world of tactical gameplay, elite weapons, competitive maps,
          and legendary clutch moments.
        </p>
        <a href="#about" class="btn">Explore More</a>
      </div>
    </div>
  </header>

  <section class="about" id="about">
    <h2 class="section-title">About CS:GO</h2>
    <div class="about-content">
      <p>
        Counter-Strike: Global Offensive, also known as CS:GO, is a tactical
        first-person shooter focused on teamwork, strategy, accuracy, and fast
        decision-making. Players compete as Terrorists or Counter-Terrorists in
        objective-based game modes such as bomb defusal and hostage rescue.
      </p>
      <br />
      <p>
        CS:GO became one of the most iconic competitive esports titles in the
        world, known for its high skill ceiling, legendary maps, and intense
        professional tournaments.
      </p>
    </div>
  </section>

  <section class="weapons" id="weapons">
    <h2 class="section-title">Popular Weapons</h2>

    <div class="cards">
      <div class="card weapon-card">
        <img
          src="https://images.unsplash.com/photo-1595590424283-b8f17842773f?auto=format&fit=crop&w=800&q=80"
          alt="AK-47"
        />
        <h3>AK-47</h3>
        <p>
          A powerful rifle favored by Terrorists. Known for one-shot headshot
          potential and high damage.
        </p>
      </div>

      <div class="card weapon-card">
        <img
          src="https://images.unsplash.com/photo-1616628182503-7ad770b25a9c?auto=format&fit=crop&w=800&q=80"
          alt="M4A4"
        />
        <h3>M4A4</h3>
        <p>
          A reliable Counter-Terrorist rifle with strong accuracy, fire rate,
          and control.
        </p>
      </div>

      <div class="card weapon-card">
        <img
          src="https://images.unsplash.com/photo-1585581720418-2f84f74d8d6b?auto=format&fit=crop&w=800&q=80"
          alt="AWP"
        />
        <h3>AWP</h3>
        <p>
          The legendary sniper rifle capable of eliminating enemies with a
          single shot.
        </p>
      </div>
    </div>
  </section>

  <section class="maps" id="maps">
    <h2 class="section-title">Famous Maps</h2>

    <div class="cards">
      <div
        class="map-card"
        style="background-image: url('https://images.unsplash.com/photo-1536152470836-b943b246224c?auto=format&fit=crop&w=800&q=80');"
      >
        <div>
          <h3>Dust II</h3>
          <p>The most iconic Counter-Strike map, famous for balanced gameplay.</p>
        </div>
      </div>

      <div
        class="map-card"
        style="background-image: url('https://images.unsplash.com/photo-1518005020951-eccb494ad742?auto=format&fit=crop&w=800&q=80');"
      >
        <div>
          <h3>Mirage</h3>
          <p>A competitive favorite featuring mid-control and tactical executes.</p>
        </div>
      </div>

      <div
        class="map-card"
        style="background-image: url('https://images.unsplash.com/photo-1519608487953-e999c86e7455?auto=format&fit=crop&w=800&q=80');"
      >
        <div>
          <h3>Inferno</h3>
          <p>Known for tight corridors, banana control, and explosive site takes.</p>
        </div>
      </div>
    </div>
  </section>

  <section class="stats" id="stats">
    <h2 class="section-title">Game Highlights</h2>

    <div class="stats-grid">
      <div class="stat-box">
        <h3>5v5</h3>
        <p>Competitive Format</p>
      </div>

      <div class="stat-box">
        <h3>30</h3>
        <p>Rounds Max</p>
      </div>

      <div class="stat-box">
        <h3>2</h3>
        <p>Main Teams</p>
      </div>

      <div class="stat-box">
        <h3>∞</h3>
        <p>Clutch Moments</p>
      </div>
    </div>
  </section>

  <section class="contact" id="contact">
    <h2 class="section-title">Join The Community</h2>

    <form onsubmit="sendMessage(event)">
      <input type="text" id="name" placeholder="Your Name" required />
      <input type="email" id="email" placeholder="Your Email" required />
      <textarea id="message" placeholder="Your Message" required></textarea>
      <button type="submit">Send Message</button>
    </form>
  </section>

  <footer>
    <p>
      © 2026 CS:GO Arena. Fan-made website. Counter-Strike and CS:GO are
      trademarks of their respective owners.
    </p>
  </footer>

  <script>
    function toggleMenu() {
      const menu = document.getElementById("menu");
      menu.classList.toggle("active");
    }

    function sendMessage(event) {
      event.preventDefault();

      const name = document.getElementById("name").value;

      alert("Thanks, " + name + "! Your message has been received.");

      event.target.reset();
    }
  </script>
</body>
</html>
```

